process.env.NODE_ENV='test';process.env.DATA_DIR=mkdtempSync(join(tmpdir(),'gather-community-'));process.env.ADMIN_EMAIL='owner@example.test';delete process.env.RESEND_API_KEY;delete process.env.EMAIL_VERIFICATION_REQUIRED;
const {server}=await import('../server/server.mjs');await new Promise(r=>server.listen(0,'127.0.0.1',r));const base=`http://127.0.0.1:${server.address().port}`;const db=new DatabaseSync(join(process.env.DATA_DIR,'gather.sqlite'));
const call=async(path,user,method='GET',body)=>{const r=await fetch(base+'/api'+path,{method,headers:{...(user?{Authorization:`Bearer ${user.token}`} : {}),...(body!==undefined?{'Content-Type':'application/json'}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});return {status:r.status,data:await r.json()};};
async function account(name,isPrivate=false){const r=await call('/auth/register',null,'POST',{username:name,email:`${name}@example.test`,displayName:name,password:'Strong-password-2026!',ageConfirmed:true,agreedRules:true,isPrivate});assert.equal(r.status,200,JSON.stringify(r.data));db.prepare('UPDATE users SET email_verified=1 WHERE id=?').run(r.data.user.id);return r.data;}
