 await test('recording notices require scoped host control and expire without deleting the live',async()=>{
 const host=await account('record_host'),viewer=await account('record_viewer');const id='record-test-live',endToken='R'.repeat(43),hash=createHash('sha256').update(endToken).digest('hex');db.prepare("INSERT INTO lives(id,host_id,title,status,created_at,kind,end_hash,end_expires) VALUES(?,?,?,'active',?,'live',?,?)").run(id,host.user.id,'Recording test',new Date().toISOString(),hash,Date.now()+60000);
 const path=`/live/${id}/recording`;assert.equal((await call(path)).data.active,false);assert.equal((await call(path,viewer,'POST',{active:true})).status,403);assert.equal((await call(path,null,'POST',{endToken:'X'.repeat(43),active:true})).status,403);assert.equal((await call(path,null,'POST',{endToken,active:true})).status,200);assert.equal((await call(path,viewer)).data.active,true);assert.equal((await call(path,null,'POST',{endToken,active:'yes'})).status,400);db.prepare('UPDATE live_recordings SET expires_at=0 WHERE live_id=?').run(id);assert.equal((await call(path,viewer)).data.active,false);assert.equal(db.prepare('SELECT status FROM lives WHERE id=?').get(id).status,'active');await call(path,null,'POST',{endToken,active:true});assert.equal((await call(path,null,'POST',{endToken,active:false})).status,200);assert.equal((await call(path)).data.active,false);db.prepare('UPDATE lives SET end_expires=0 WHERE id=?').run(id);assert.equal((await call(path,null,'POST',{endToken,active:true})).status,403);db.prepare("UPDATE lives SET status='ended' WHERE id=?").run(id);
 });
 await test('reading a batch clears highlights while retaining history and newer unread notifications',async()=>{
 const u=await account('notice_reader'),other=await account('notice_other');const insert=db.prepare("INSERT INTO notifications(user_id,actor_id,kind,created_at) VALUES(?,?,'follow',?)");const first=Number(insert.run(u.user.id,b.user.id,new Date().toISOString()).lastInsertRowid),second=Number(insert.run(u.user.id,c.user.id,new Date().toISOString()).lastInsertRowid),foreign=Number(insert.run(other.user.id,b.user.id,new Date().toISOString()).lastInsertRowid);
 const result=await call('/notifications/read',u,'POST',{ids:[first,foreign]});assert.equal(result.status,200);assert.equal(result.data.unread,1);const history=(await call('/notifications',u)).data;assert.ok(history.find(n=>n.id===first).seen);assert.equal(history.find(n=>n.id===second).seen,false);assert.equal(db.prepare('SELECT seen FROM notifications WHERE id=?').get(foreign).seen,0);assert.equal((await call('/notifications/read',u,'POST',{ids:['bad']})).status,400);assert.equal((await call('/notifications/read',u,'POST',{})).data.unread,0);assert.equal((await call('/notifications',u)).data.length,2);
 });
