 assert.equal((await call('/live/battle-users')).status,401);let rows=(await call('/live/battle-users',viewer)).data;assert.ok(rows.some(p=>p.id===host.user.id));assert.ok(rows.some(p=>p.id===guest.user.id));assert.equal(rows.some(p=>p.id===viewer.user.id),false);
