 await test('startup creates one public official Gather page with a wallet and signup follows',async()=>{const page=(await call('/official',a)).data;assert.ok(page?.id);assert.equal(page.displayName,'Gather');assert.equal(page.isPrivate,false);assert.notEqual(page.id,owner.user.id);assert.equal(db.prepare('SELECT COUNT(*) n FROM users WHERE official=1').get().n,1);assert.equal(db.prepare('SELECT balance_gc FROM gc_wallets WHERE user_id=?').get(page.id).balance_gc,'0');assert.equal((await call(`/users/${page.id}`,a)).data.isFollowing,true);const again=(await call('/admin/official',owner,'POST',{})).data;assert.equal(again.id,page.id);assert.equal(db.prepare('SELECT COUNT(*) n FROM users WHERE official=1').get().n,1);});
 await test('post audiences enforce mutual friendship, self privacy and explicit public consent',async()=>{const self=await call('/posts',a,'POST',{body:'Private thought',audience:'self'});assert.equal(self.status,200);assert.equal((await call(`/posts/${self.data.id}`,b)).status,404);assert.equal((await call(`/public/posts/${self.data.id}`)).status,404);const friends=(await call('/posts',a,'POST',{body:'For friends',audience:'friends'})).data;assert.equal((await call(`/posts/${friends.id}`,b)).status,404);await call(`/users/${a.user.id}/follow`,b,'PUT');assert.equal((await call('/follow-requests',a)).data.length,1);assert.equal((await call(`/follow-requests/${b.user.id}`,c,'POST',{action:'accept'})).status,404);await call(`/follow-requests/${b.user.id}`,a,'POST',{action:'accept'});assert.equal((await call(`/posts/${friends.id}`,b)).status,404);await call(`/users/${b.user.id}/follow`,a,'PUT');assert.equal((await call(`/posts/${friends.id}`,b)).status,200);assert.equal((await call('/posts',a,'POST',{body:'Public',audience:'public'})).status,400);const p=await call('/posts',a,'POST',{body:'Public',audience:'public',confirmPublic:true});assert.equal((await call(`/public/posts/${p.data.id}`)).status,200);assert.ok(!(await call('/posts',c)).data.posts.some(p=>p.id===friends.id));await call(`/users/${b.user.id}/follow`,a,'DELETE');assert.equal((await call(`/posts/${friends.id}`,b)).status,404);});
 await test('private gallery and media use the post audience; photo ownership cannot be stolen',async()=>{const image=(await call('/uploads',a,'POST',{base64:'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aC+0AAAAASUVORK5CYII='})).data;assert.equal((await fetch(base+image.url)).status,404);assert.equal((await call('/gallery',b)).data.length,0);assert.equal((await fetch(base+image.url,{headers:{Authorization:`Bearer ${a.token}`}})).status,200);assert.equal((await call('/posts',b,'POST',{body:'Steal',mediaId:image.id,audience:'public'})).status,400);const p=(await call('/posts',a,'POST',{body:'Private photo',mediaId:image.id,audience:'self'})).data;assert.equal((await fetch(base+image.url,{headers:{Authorization:`Bearer ${b.token}`}})).status,404);await call(`/gallery/${image.id}`,a,'DELETE');assert.equal((await call('/gallery',a)).data.length,0);assert.equal((await call(`/posts/${p.id}`,a)).status,200);});
