 await test('contact discovery requires consent, opt-in, verification; never returns email',async()=>{assert.equal((await call('/contacts',a,'POST',{emails:['bob@example.test']})).status,400);assert.equal((await call('/contacts',a,'POST',{consent:true,emails:['bob@example.test']})).data.length,0);await call('/account',b,'PATCH',{discoverable:true});const matches=(await call('/contacts',a,'POST',{consent:true,emails:['BOB@example.test']})).data;assert.equal(matches[0].id,b.user.id);assert.equal(matches[0].email,undefined);await call('/account',b,'PATCH',{discoverable:false});assert.equal((await call('/contacts',a)).data.length,0);await call('/contacts',a,'DELETE');assert.equal(db.prepare('SELECT COUNT(*) n FROM contact_matches WHERE owner_id=?').get(a.user.id).n,0);});
 await test('official Gather page is separate from admin and auto-follow happens only on creation/signup',async()=>{assert.equal((await call('/admin/official',b,'POST',{})).status,403);const page=(await call('/admin/official',owner,'POST',{})).data;assert.notEqual(page.id,owner.user.id);assert.equal((await call(`/users/${page.id}`,b)).data.isFollowing,true);await call(`/users/${page.id}/follow`,b,'DELETE');await call('/admin/official',owner,'POST',{});assert.equal((await call(`/users/${page.id}`,b)).data.isFollowing,false);const d=await account('dana');assert.equal((await call(`/users/${page.id}`,d)).data.isFollowing,true);const p=(await call('/admin/official/posts',owner,'POST',{body:'Welcome to Gather!'})).data;assert.equal((await call(`/public/posts/${p.id}`)).data.author.id,page.id);});
 await test('HTTPS bio links validate credentials and preference settings suppress new notifications',async()=>{assert.equal((await call('/account',a,'PATCH',{socials:[{label:'Bad',url:'javascript:alert(1)'}]})).status,400);assert.equal((await call('/account',a,'PATCH',{socials:[{label:'Bad',url:'https://user:password@example.com'}]})).status,400);assert.equal((await call('/account',a,'PATCH',{socials:[{label:'Site',url:'https://example.com'}],notificationPreferences:{social:false}})).status,200);const p=(await call('/posts',a,'POST',{body:'Public again',audience:'public',confirmPublic:true})).data;const before=(await call('/notifications',a)).data.length;await call(`/posts/${p.id}/like`,c,'PUT');assert.equal((await call('/notifications',a)).data.length,before);});
 await test('joined and discover Gathering sections remain separate before and after membership changes',async()=>{const owner=await account('segmentowner'),reader=await account('segmentreader');const g=(await call('/gatherings',owner,'POST',{name:'Segment test',topic:'Membership',isPrivate:true})).data;let joined=(await call('/gatherings?section=joined',owner)).data;assert.ok(joined.some(v=>v.id===g.id));assert.ok(!(await call('/gatherings?section=discover',owner)).data.some(v=>v.id===g.id));assert.ok((await call('/gatherings?section=discover',reader)).data.some(v=>v.id===g.id));await call(`/gatherings/${g.id}/join`,reader,'POST',{});assert.ok(!(await call('/gatherings?section=joined',reader)).data.some(v=>v.id===g.id));assert.equal((await call('/gatherings?section=discover',reader)).data.find(v=>v.id===g.id).membership,'pending');await call(`/gatherings/${g.id}/members/${reader.user.id}`,owner,'PATCH',{action:'accept'});assert.ok((await call('/gatherings?section=joined',reader)).data.some(v=>v.id===g.id));assert.ok(!(await call('/gatherings?section=discover',reader)).data.some(v=>v.id===g.id));await call(`/gatherings/${g.id}/join`,reader,'DELETE');assert.ok(!(await call('/gatherings?section=joined',reader)).data.some(v=>v.id===g.id));assert.ok((await call('/gatherings?section=discover',reader)).data.some(v=>v.id===g.id));});
 await test('live thumbnails require host controls, expire, clear and respect broadcast visibility',async()=>{const {setTestLiveService}=await import('../server/live.mjs');setTestLiveService({createRoom:async()=>{},removeParticipant:async()=>{},deleteRoom:async()=>{}});const host=await account('thumbhost'),viewer=await account('thumbviewer');const l=(await call('/live',host,'POST',{title:'Preview live',publicConfirmed:true})).data;const token=(await call(`/live/${l.id}/token`,host,'POST',{})).data.endToken;const path=`/live/${l.id}/thumbnail`,image='data:image/jpeg;base64,'+Buffer.from([255,216,255,224,0,2,255,217]).toString('base64');assert.equal((await call(path,viewer,'POST',{endToken:'x'.repeat(43),image})).status,403);assert.equal((await call(path,null,'POST',{endToken:token,image:'data:image/jpeg;base64,YWJjZA=='})).status,400);assert.equal((await call(path,null,'POST',{endToken:token,image})).status,200);assert.equal((await call(`/live/${l.id}`,viewer)).data.thumbnail,image);assert.equal((await call(path,null,'POST',{endToken:token,image})).status,429);await call(`/users/${host.user.id}/block`,viewer,'PUT');assert.equal((await call(`/live/${l.id}`,viewer)).status,404);assert.ok(!(await call('/live',viewer)).data.some(v=>v.id===l.id));db.prepare('UPDATE live_thumbnails SET updated_at=? WHERE live_id=?').run(Date.now()-46000,l.id);assert.equal((await call(`/live/${l.id}`)).data.thumbnail,null);assert.equal((await call(path,null,'POST',{endToken:token,image})).status,200);assert.equal((await call(path,null,'POST',{endToken:token,image:null})).status,200);assert.equal((await call(`/live/${l.id}`)).data.thumbnail,null);await call(`/live/${l.id}/end-browser`,null,'POST',{endToken:token});assert.equal((await call(path,null,'POST',{endToken:token,image})).status,404);});
 await test('six broadcaster capacity and scoped browser end controls',async()=>{const {setTestLiveService}=await import('../server/live.mjs');setTestLiveService({createRoom:async()=>{},removeParticipant:async()=>{},deleteRoom:async()=>{}});const host=await account('sixhost');const guests=[];for(let n=0;n<6;n++)guests.push(await account(`sixguest${n}`));const l=(await call('/live',host,'POST',{title:'Six people',publicConfirmed:true})).data;for(const g of guests.slice(0,5)){assert.equal((await call(`/live/${l.id}/invite`,host,'POST',{userId:g.user.id})).status,200);assert.equal((await call(`/live/${l.id}/accept`,g,'POST',{})).status,200);const t=(await call(`/live/${l.id}/token`,g,'POST',{})).data;assert.equal(t.canPublish,true);assert.equal(t.endToken,undefined);}assert.equal((await call(`/live/${l.id}/invite`,host,'POST',{userId:guests[5].user.id})).status,409);assert.equal((await call(`/live/${l.id}`)).data.guestIds.length,5);const t=(await call(`/live/${l.id}/token`,host,'POST',{})).data;assert.equal(t.endToken.length,43);assert.equal((await call(`/live/${l.id}/end-browser`,null,'POST',{endToken:'x'.repeat(43)})).status,403);assert.equal((await call(`/live/${l.id}/end-browser`,null,'POST',{endToken:t.endToken})).status,200);assert.equal((await call(`/live/${l.id}/token`,null,'POST',{})).status,404);});
 await test('live tokens enforce invited guests, verified chat, and host moderation',async()=>{const {setTestLiveService}=await import('../server/live.mjs');const events=[];setTestLiveService({createRoom:async()=>{},removeParticipant:async(...args)=>events.push(['remove',...args]),deleteRoom:async()=>{}});assert.equal((await call('/live',a,'POST',{title:'Garden live'})).status,400);const l=(await call('/live',a,'POST',{title:'Garden live',publicConfirmed:true})).data;assert.equal((await call('/live',a,'POST',{title:'Duplicate',publicConfirmed:true})).status,409);const viewer=(await call(`/live/${l.id}/token`,null,'POST',{})).data;assert.equal(viewer.canPublish,false);const claims=JSON.parse(Buffer.from(viewer.token.split('.')[1],'base64url').toString());assert.equal(claims.video.canPublish,false);assert.equal(claims.video.canPublishData,false);assert.equal((await call(`/live/${l.id}/invite`,b,'POST',{userId:c.user.id})).status,403);await call(`/live/${l.id}/invite`,a,'POST',{userId:b.user.id});assert.equal((await call(`/live/${l.id}/accept`,c,'POST',{})).status,409);const results=await Promise.all([call(`/live/${l.id}/accept`,b,'POST',{}),call(`/live/${l.id}/accept`,b,'POST',{})]);assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);assert.equal((await call(`/live/${l.id}/token`,b,'POST',{})).data.canPublish,true);assert.equal((await call(`/live/${l.id}/invite`,a,'POST',{userId:c.user.id})).status,200);assert.equal((await call(`/live/${l.id}/chat`,null,'POST',{body:'Anonymous'})).status,401);await call(`/live/${l.id}/chat`,b,'POST',{body:'Hello'});assert.equal((await call(`/live/${l.id}/chat`)).data.length,1);await call(`/live/${l.id}/guest`,a,'DELETE');assert.equal((await call(`/live/${l.id}/token`,b,'POST',{})).data.canPublish,false);assert.equal(events.length,1);await call(`/live/${l.id}/end`,a,'POST',{});assert.equal((await call(`/live/${l.id}/token`,null,'POST',{})).status,404);});
