 await test('presence expires per session and appear-offline hides activity from other members',async()=>{const p=await account('presence'),viewer=await account('watcher');assert.equal((await call('/presence',null,'POST',{active:true})).status,401);assert.equal((await call('/presence',p,'POST',{active:'yes'})).status,400);await call('/presence',p,'POST',{active:true,userId:viewer.user.id});assert.equal((await call(`/users/${p.user.id}`,viewer)).data.isOnline,true);assert.equal((await call(`/public/profiles/${p.user.id}`)).data.isOnline,false);await call('/account',p,'PATCH',{appearOffline:true});assert.equal((await call(`/users/${p.user.id}`,viewer)).data.isOnline,false);assert.equal((await call(`/presence?ids=${p.user.id}`,viewer)).data[0].isOnline,false);await call('/account',p,'PATCH',{appearOffline:false});const second=(await call('/auth/login',null,'POST',{email:'presence@example.test',password:'Strong-password-2026!'})).data;await call('/presence',second,'POST',{active:true});await call('/presence',p,'POST',{active:false});assert.equal((await call(`/users/${p.user.id}`,viewer)).data.isOnline,true);db.prepare('UPDATE sessions SET presence_until=0 WHERE user_id=?').run(p.user.id);assert.equal((await call(`/users/${p.user.id}`,viewer)).data.isOnline,false);await call('/presence',p,'POST',{active:true});await call(`/users/${viewer.user.id}/block`,p,'PUT');assert.equal((await call(`/presence?ids=${p.user.id}`,viewer)).data[0].isOnline,false);});
 await test('friend requests require recipient consent and suggestions count mutual friendships',async()=>{const x=await account('alex',true),y=await account('blair'),z=await account('casey');const post=(await call('/posts',x,'POST',{body:'Friends only',audience:'friends'})).data;assert.equal((await call('/friend-requests',x,'POST',{userId:x.user.id})).status,404);assert.equal((await call('/friend-requests',x,'POST',{userId:y.user.id})).status,200);assert.equal((await call('/friend-requests',x,'POST',{userId:y.user.id})).status,200);assert.equal((await call('/friend-requests',y)).data.filter(p=>p.id===x.user.id).length,1);assert.equal((await call(`/friend-requests/${x.user.id}`,z,'POST',{action:'accept'})).status,404);assert.equal((await call('/friend-requests',y,'POST',{userId:x.user.id})).status,409);assert.equal((await call(`/posts/${post.id}`,y)).status,404);await call(`/friend-requests/${x.user.id}`,y,'POST',{action:'accept'});assert.equal((await call(`/posts/${post.id}`,y)).status,200);assert.equal((await call(`/users/${x.user.id}`,y)).data.isFriend,true);await call('/friend-requests',y,'POST',{userId:z.user.id});await call(`/friend-requests/${y.user.id}`,z,'POST',{action:'accept'});const suggested=(await call('/friend-suggestions',x)).data.find(p=>p.id===z.user.id);assert.equal(suggested.mutualFriends,1);assert.ok(!(await call('/friend-suggestions',x)).data.some(p=>p.id===y.user.id));await call(`/users/${z.user.id}/block`,x,'PUT');assert.ok(!(await call('/friend-suggestions',x)).data.some(p=>p.id===z.user.id));assert.equal((await call('/friend-requests',z,'POST',{userId:x.user.id})).status,404);});

