 await test('call history is private and records denial, cancellation, missed calls and completed sessions',async()=>{const {setTestLiveService}=await import('../server/live.mjs');setTestLiveService({createRoom:async()=>{},deleteRoom:async()=>{},removeParticipant:async()=>{}});const host=await account('history_host'),friend=await account('history_friend'),other=await account('history_other');await call('/friend-requests',host,'POST',{userId:friend.user.id});await call(`/friend-requests/${host.user.id}`,friend,'POST',{action:'accept'});const start=async()=>{const r=await call('/rooms',host,'POST',{kind:'call',userId:friend.user.id});assert.equal(r.status,200);return r.data.id;};let id=await start();await call(`/rooms/${id}/leave`,friend,'POST',{});assert.equal((await call('/rooms/history',friend)).data[0].status,'denied');id=await start();await call(`/rooms/${id}/end`,host,'POST',{});assert.equal((await call('/rooms/history',host)).data.find(l=>l.id===id).status,'canceled');id=await start();db.prepare('UPDATE call_logs SET started_at=? WHERE room_id=?').run(Date.now()-61000,id);const missed=(await call('/rooms/history',friend)).data.find(l=>l.id===id);assert.equal(missed.status,'missed');assert.equal(missed.direction,'incoming');assert.equal((await call(`/rooms/${id}/join`,friend,'POST',{})).status,404);await call('/rooms/history',friend);assert.equal(db.prepare("SELECT COUNT(*) n FROM notifications WHERE user_id=? AND kind='call_missed'").get(friend.user.id).n,1);assert.deepEqual((await call('/rooms/history',other)).data,[]);id=await start();await call(`/rooms/${id}/join`,friend,'POST',{});await call(`/rooms/${id}/leave`,host,'POST',{});const completed=(await call('/rooms/history',host)).data.find(l=>l.id===id);assert.equal(completed.status,'completed');assert.equal(completed.direction,'outgoing');assert.ok(completed.acceptedAt);assert.ok(completed.durationSeconds>=0);});
 await test('call settings enforce recipient choice, persist timeout and allow direct joining without approval',async()=>{const {setTestLiveService}=await import('../server/live.mjs');setTestLiveService({createRoom:async()=>{},deleteRoom:async()=>{},removeParticipant:async()=>{}});const caller=await account('settings_caller'),recipient=await account('settings_recipient'),outsider=await account('settings_other');assert.equal((await call('/rooms',caller,'POST',{kind:'call',userId:recipient.user.id})).status,403);assert.equal((await call('/rooms/settings',recipient,'PATCH',{allowCalls:'everyone',notifications:false,ringSeconds:30})).status,200);assert.equal((await call('/rooms/settings',recipient)).data.ringSeconds,30);assert.equal((await call('/rooms/settings',recipient,'PATCH',{ringSeconds:1})).status,400);const r=(await call('/rooms',caller,'POST',{kind:'call',userId:recipient.user.id})).data;assert.ok(r.id);assert.equal(r.peer.id,recipient.user.id);assert.equal((await call('/rooms',recipient)).data.find(room=>room.id===r.id).peer.id,caller.user.id);assert.equal(db.prepare("SELECT COUNT(*) n FROM notifications WHERE user_id=? AND kind='call_invite'").get(recipient.user.id).n,0);assert.equal((await call(`/rooms/${r.id}/token`,outsider,'POST',{})).status,404);assert.equal((await call(`/rooms/${r.id}/token`,recipient,'POST',{})).status,200);await call(`/rooms/${r.id}/end`,caller,'POST',{});await call('/rooms/settings',recipient,'PATCH',{allowCalls:'off'});assert.equal((await call('/rooms',caller,'POST',{kind:'call',userId:recipient.user.id})).status,403);await call('/rooms/settings',recipient,'PATCH',{allowCalls:'everyone'});await call(`/users/${caller.user.id}/block`,recipient,'PUT');assert.equal((await call('/rooms',caller,'POST',{kind:'call',userId:recipient.user.id})).status,403);});
